import React, { useState, useEffect } from "react";
import { useNavigate } from "react-router-dom";

const Stall = () => {
    const navigate = useNavigate();
    const [rotate, setRotate] = useState({ x: 10, y: 0 });

    // Track mouse movement to rotate the "camera"
    useEffect(() => {
        const handleMouseMove = (e) => {
            // Calculate rotation based on mouse position relative to screen center
            const xRotation = (window.innerHeight / 2 - e.clientY) / 25;
            const yRotation = (e.clientX - window.innerWidth / 2) / 25;
            setRotate({ x: xRotation + 10, y: yRotation });
        };

        window.addEventListener("mousemove", handleMouseMove);
        return () => window.removeEventListener("mousemove", handleMouseMove);
    }, []);

    return (
        <div className="min-h-screen bg-slate-950 flex items-center justify-center overflow-hidden perspective-1000">
            {/* The 3D World Container */}
            <div
                className="relative w-[600px] h-[400px] transition-transform duration-200 ease-out"
                style={{
                    transformStyle: 'preserve-3d',
                    transform: `rotateX(${rotate.x}deg) rotateY(${rotate.y}deg)`
                }}
            >
                {/* 1. FLOOR */}
                <div
                    className="absolute inset-0 bg-slate-800 border-2 border-slate-700 shadow-[inset_0_0_50px_rgba(0,0,0,0.5)]"
                    style={{ transform: 'rotateX(90deg) translateZ(-200px)' }}
                >
                    <div className="w-full h-full opacity-20" style={{ backgroundImage: 'radial-gradient(circle, #475569 1px, transparent 1px)', backgroundSize: '20px 20px' }}></div>
                </div>

                {/* 2. BACK WALL */}
                <div
                    className="absolute inset-0 bg-gradient-to-br from-indigo-900 to-blue-800 border-4 border-blue-500/50 flex flex-col items-center justify-center text-white shadow-2xl"
                    style={{ transform: 'translateZ(-200px)' }}
                >
                    <h2 className="text-5xl font-black tracking-tighter drop-shadow-lg">VANTAGE</h2>
                    <div className="w-48 h-1 bg-blue-400 my-4 shadow-[0_0_15px_#60a5fa]"></div>
                    <p className="text-sm uppercase tracking-[0.3em] text-blue-200">Virtual Experience</p>
                </div>

                {/* 3. LEFT WALL */}
                <div
                    className="absolute top-0 bottom-0 w-[400px] bg-slate-900 border-r-2 border-blue-500/30"
                    style={{ transform: 'rotateY(90deg) translateZ(-300px)' }}
                ></div>

                {/* 4. RIGHT WALL */}
                <div
                    className="absolute top-0 bottom-0 w-[400px] bg-slate-900 border-l-2 border-blue-500/30"
                    style={{ transform: 'rotateY(-90deg) translateZ(-300px)' }}
                ></div>

                {/* 5. RECEPTION DESK (3D Object) */}
                <div
                    className="absolute bottom-0 left-1/2 -translate-x-1/2 w-64 h-32 bg-white shadow-2xl flex items-center justify-center border-b-8 border-gray-300"
                    style={{ transform: 'translateZ(50px)' }}
                >
                    <div className="text-center text-blue-900 font-bold">RECEPTION</div>
                    {/* Desk Top */}
                    <div className="absolute -top-4 left-0 w-full h-4 bg-gray-100" style={{ transform: 'rotateX(-90deg)', transformOrigin: 'bottom' }}></div>
                </div>

                {/* 6. FLOATING INTERACTIVE ITEM */}
                <div
                    className="absolute top-10 right-10 w-24 h-24 bg-yellow-400 rounded-full flex items-center justify-center shadow-[0_0_30px_rgba(250,204,21,0.5)] animate-bounce cursor-pointer group"
                    style={{ transform: 'translateZ(150px)' }}
                >
                    <span className="text-4xl group-hover:scale-125 transition-transform">💎</span>
                </div>
            </div>

            {/* UI HUD Layer (Standard 2D Overlay) */}
            <div className="absolute inset-0 pointer-events-none">
                <div className="absolute top-10 left-10 pointer-events-auto">
                    <button
                        onClick={() => navigate("/")}
                        className="text-white border border-white/20 px-6 py-2 rounded-full hover:bg-blue-600 transition-all backdrop-blur-md"
                    >
                        ← Back to Lobby
                    </button>
                </div>

                <div className="absolute bottom-10 right-10 text-right">
                    <div className="text-blue-400 text-xs uppercase tracking-widest mb-1 font-mono">Sensors Active</div>
                    <div className="text-white text-xl font-light">MOVE MOUSE TO EXPLORE</div>
                </div>
            </div>
        </div>
    );
};

export default Stall;
